draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var wx = W * 0.72;
var mid = H * 0.42;

ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(wx, 16); ctx.lineTo(wx, H - 30); ctx.stroke();
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var k;
for (k = 0; k < 12; k++) {
  var yy = 16 + k * (H - 46) / 12;
  ctx.beginPath(); ctx.moveTo(wx, yy); ctx.lineTo(wx + 10, yy + 8); ctx.stroke();
}
ctx.fillStyle = C.figure;
ctx.fillText("wall, area A", wx + 14, 26);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(wx - 150, mid); ctx.lineTo(wx - 22, mid); ctx.stroke();
ctx.beginPath();
ctx.moveTo(wx - 22, mid); ctx.lineTo(wx - 32, mid - 5); ctx.lineTo(wx - 32, mid + 5);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("before:  +m v_x", wx - 150, mid - 10);

var mid2 = H * 0.72;
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(wx - 22, mid2); ctx.lineTo(wx - 150, mid2); ctx.stroke();
ctx.beginPath();
ctx.moveTo(wx - 150, mid2); ctx.lineTo(wx - 140, mid2 - 5); ctx.lineTo(wx - 140, mid2 + 5);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("after:  - m v_x", wx - 150, mid2 - 10);
ctx.fillStyle = C.accent;
ctx.fillText("change of 2 m v_x, so the wall gets 2 m v_x", 16, H - 10);

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.strokeRect(wx - 150, 16, 150, H - 46);
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("only molecules inside this slab,", 16, H * 0.16);
ctx.fillText("of length v_x times dt, can reach", 16, H * 0.16 + 14);
ctx.fillText("the wall in time dt", 16, H * 0.16 + 28);
